class References(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.fixture = b.read(b.ROOT / b.FIXTURE)

    def test_source_hashes_locators_and_schema(self):
        b.validate_fixture(self.fixture)

    def test_denominator_cannot_drift(self):
        f = copy.deepcopy(self.fixture); f['protocol']['chronology_denominator'] = 11
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_duplicate_reference_rejected(self):
        f = copy.deepcopy(self.fixture); f['chronology'][1]['id'] = f['chronology'][0]['id']
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_bad_manual_arithmetic_rejected(self):
        f = copy.deepcopy(self.fixture); f['chronology'][0]['expected']['amount'] = '9'
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_source_quote_tamper_rejected(self):
        f = copy.deepcopy(self.fixture); f['source_references'][0]['supports'][0]['quote'] = 'wrong'
        with self.assertRaises(ValueError): b.validate_fixture(f)

    def test_unknown_is_not_invented_answer(self):
        r = self.fixture['source_references'][3]
        self.assertTrue(b.admit_source_answer(r, 'unresolved'))
        self.assertFalse(b.admit_source_answer(r, '14575000000 USD of effective floating-rate debt'))
        self.assertFalse(b.admit_source_answer(r, None))

    def test_exposure_and_dependent_test_families(self):
        e = b.exposure_register()
        self.assertEqual(e['issuer_count'], 9)
        self.assertEqual({r['issuer'] for r in e['families'] if r['proposed_role']=='test_candidate'}, {'jpmorgan','ping_an','munich_re'})
        self.assertTrue(all(r['source_acquisition_qa_exposure'] and not r['clean_heldout'] for r in e['families']))
        self.assertEqual(e['window']['years_inclusive'], 8)

    def test_preparation_tamper(self):
        d = b.preparation(); b.verify_preparation(d)
        d['preparation']['references']['chronology'][0]['expected']['amount'] = '100'
        with self.assertRaisesRegex(ValueError, 'preparation hash'): b.verify_preparation(d)

    def test_changed_reference_hash(self):
        d = b.preparation(); d['preparation']['reference_sha256'] = '0'*64
        d['preparation_sha256'] = b.digest(d['preparation'])
        with self.assertRaisesRegex(ValueError, 'reference hash'): b.verify_preparation(d)

    def test_changed_file_pin(self):
        d = b.preparation(); d['preparation']['input_hashes'][b.FIXTURE] = '0'*64
        d['preparation_sha256'] = b.digest(d['preparation'])
        with self.assertRaisesRegex(ValueError, 'frozen input'): b.verify_preparation(d)


class Chronology(unittest.TestCase):
    def setUp(self):
        self.cases = b.read(b.ROOT / b.FIXTURE)['chronology']
        self.answers = [{'id': c['id'], 'answer': copy.deepcopy(c['expected'])} for c in self.cases]

    def test_evaluated_component_matches_independent_references(self):
        result = b.score_chronology(self.cases, b.evaluate_chronology(self.cases))
        self.assertTrue(result['all_passed'], result)
        self.assertEqual(result['by_kind'], {'valid': {'denominator':3,'passed':3}, 'invalid': {'denominator':9,'passed':9}})

    def test_correct(self):
        self.assertTrue(b.score_chronology(self.cases,self.answers)['all_passed'])

    def test_missing_not_excluded(self):
        result=b.score_chronology(self.cases,self.answers[:-1])
        self.assertEqual((result['denominator'],result['passed']),(12,11))

    def test_extra(self):
        self.answers.append({'id':'extra','answer':{}})
        self.assertFalse(b.score_chronology(self.cases,self.answers)['all_passed'])

    def test_duplicate(self):
        self.answers.append(self.answers[0])
        self.assertEqual(b.score_chronology(self.cases,self.answers)['passed'],11)

    def test_malformed(self):
        self.answers[0]=None
        self.assertFalse(b.score_chronology(self.cases,self.answers)['all_passed'])
        self.assertEqual(b.score_chronology(self.cases,None)['passed'],0)

    def test_wrong_amount_context_period_and_code(self):
        for key,value in [('amount','0'),('context',{}),('period',{'start':'2024-04-02','end':'2024-07-01'})]:
            a=copy.deepcopy(self.answers); a[0]['answer'][key]=value
            self.assertEqual(b.score_chronology(self.cases,a)['passed'],11)
        self.answers[-1]['answer']['code']='CONTEXT_MISMATCH'
        self.assertEqual(b.score_chronology(self.cases,self.answers)['passed'],11)

    def test_unexpected_rejection_abstention_crash_timeout(self):
        for status in ['rejected','abstain','crash','timeout']:
            a=copy.deepcopy(self.answers); a[0]['answer']={'status':status}
            self.assertEqual(b.score_chronology(self.cases,a)['passed'],11)


class Workloads(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.cells=b.read(b.ROOT/b.FIXTURE)['workloads']
        cls.observations=[b.execute_workload(c) for c in cls.cells]
        cls.refs=[{**c,'independent_oracle':b.independent_enumeration(c)} for c in cls.cells]

    def test_complete_partial_and_unsupported(self):
        for c,o in zip(self.refs,self.observations):
            self.assertTrue(b.score_workload(c,o)['passed'], b.score_workload(c,o))
        self.assertEqual(self.observations[3]['result']['coverage']['unresolved'],30)
        self.assertEqual(self.observations[4]['result']['status'],'UnsupportedFragment')

    def test_independent_feasible_sets_nontrivial(self):
        self.assertEqual([sum(r['feasible'] for r in c['independent_oracle']) for c in self.refs[:3]],[1,5,16])

    def test_omitted_branch_rejected(self):
        o=copy.deepcopy(self.observations[2]);o['result']['cells'].pop()
        self.assertFalse(b.score_workload(self.refs[2],o)['passed'])

    def test_fabricated_output_rejected(self):
        o=copy.deepcopy(self.observations[1]);o['result']['cells'][0]['outputs']['weighted_sum']='999'
        self.assertFalse(b.score_workload(self.refs[1],o)['passed'])

    def test_false_complete_rejected(self):
        o=copy.deepcopy(self.observations[3]);o['result']['coverage'].update(complete=True,unresolved=0)
        self.assertFalse(b.score_workload(self.refs[3],o)['passed'])

    def test_missing_measurements_rejected(self):
        for key in b.MEASUREMENTS:
            o=copy.deepcopy(self.observations[0]);del o['metrics'][key]
            self.assertFalse(b.score_workload(self.refs[0],o)['passed'],key)

    def test_missing_reply_rejected(self):
        self.assertFalse(b.score_workload(self.refs[0],{})['passed'])

    def test_child_timeout_and_crash(self):
        def timeout(*args,**kwargs): raise subprocess.TimeoutExpired(args[0],1)
        self.assertEqual(b.run_child(self.cells[0],1,timeout)['failure'],'timeout')
        def crash(*args,**kwargs): return subprocess.CompletedProcess(args[0],1,'','deliberate test failure')
        self.assertEqual(b.run_child(self.cells[0],1,crash)['failure'],'child_exit')

    def test_nonobject_child_json_is_recorded_failure(self):
        for payload in (None, [], 17, 'text', True):
            with self.subTest(payload=payload):
                def runner(*args, **kwargs):
                    return subprocess.CompletedProcess(args[0], 0, json.dumps(payload), '')
                observed = b.run_child(self.cells[0], 1, runner)
                self.assertEqual(observed['failure'], 'malformed_response')
                self.assertEqual(observed['response'], payload)
                self.assertFalse(b.score_workload(self.refs[0], observed)['passed'])
                self.assertFalse(b.score_workload(self.refs[0], payload)['passed'])

    def test_nested_malformed_reply_is_rejected_without_exception(self):
        paths = [('metrics',), ('result',), ('result', 'coverage'),
                 ('result', 'cells'), ('result', 'cells', 0),
                 ('result', 'cells', 0, 'witness'),
                 ('result', 'cells', 0, 'outputs'),
                 ('result', 'cells', 1, 'conflict'),
                 ('result', 'coverage', 'unvisited')]
        for path in paths:
            for invalid in (None, [], 17):
                with self.subTest(path=path, invalid=invalid):
                    observed = copy.deepcopy(self.observations[0]); target = observed
                    for key in path[:-1]: target = target[key]
                    target[path[-1]] = invalid
                    self.assertFalse(b.score_workload(self.refs[0], observed)['passed'])

    def test_unsupported_coverage_cannot_fabricate_certainty(self):
        metric_for = {'total': 'solver_total_branches', 'unresolved': 'unresolved_branches',
                      'completed': 'completed_branches', 'feasible': 'retained_feasible_branches',
                      'infeasible': 'infeasible_branches'}
        mutations = [('total', 0), ('unresolved', 0), ('completed', 1),
                     ('feasible', 1), ('infeasible', 1), ('complete', True),
                     ('completed', False), ('feasible', False), ('infeasible', False)]
        for key, value in mutations:
            with self.subTest(key=key, value=value):
                observed = copy.deepcopy(self.observations[4])
                observed['result']['coverage'][key] = value
                if key in metric_for: observed['metrics'][metric_for[key]] = value
                observed['metrics']['output_bytes'] = len(b.canonical(observed['result']))
                score = b.score_workload(self.refs[4], observed)
                self.assertFalse(score['passed'], score)
                self.assertFalse(any('bytes mismatch' in e or 'measurement mismatch' in e for e in score['errors']))

    def test_unsupported_missing_unknown_counts_rejected(self):
        for key in ('total', 'unresolved', 'completed', 'feasible', 'infeasible'):
            observed = copy.deepcopy(self.observations[4])
            del observed['result']['coverage'][key]
            observed['metrics']['output_bytes'] = len(b.canonical(observed['result']))
            self.assertFalse(b.score_workload(self.refs[4], observed)['passed'], key)

    def test_unsupported_unknown_measurements_must_be_explicit(self):
        for key in ('solver_total_branches', 'unresolved_branches'):
            observed = copy.deepcopy(self.observations[4]); del observed['metrics'][key]
            self.assertFalse(b.score_workload(self.refs[4], observed)['passed'], key)

    def test_malformed_child_replies_persist_all_scheduled_repetitions(self):
        # Use the real transport decoder, evaluator, scorer, renderer and CLI writes.
        real_child = b.run_child
        malformed = [None, [], 17, {'result': {}, 'metrics': None}]
        observations = {c['id']: o for c, o in zip(self.cells, self.observations)}
        calls = []
        def child(cell, timeout):
            n = len(calls); calls.append(cell['id'])
            payload = malformed[n] if n < len(malformed) else observations[cell['id']]
            def runner(*args, **kwargs):
                return subprocess.CompletedProcess(args[0], 0, json.dumps(payload), '')
            return real_child(cell, timeout, runner)
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory)
            (output / 'benchmark.json').write_text(json.dumps(b.preparation()))
            with patch.object(cli, 'OUTPUT', output), patch.object(b, 'run_child', side_effect=child), \
                 patch.object(b, 'run_checks', return_value=[{'exit_code': 0, 'command': ['test-only gate stub']}]), \
                 contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(cli.main(['--evaluate']), 1)
            document = b.read(output / 'benchmark.json'); run = document['runs'][-1]
            rows = run['workload_repetitions']
            self.assertEqual(len(calls), 15)
            self.assertEqual(len(rows), 15)
            self.assertEqual(run['workload_runs_denominator'], 15)
            self.assertEqual(run['workload_runs_passed'], 11)
            self.assertEqual([(r['id'], r['repetition']) for r in rows],
                             [(c['id'], n) for c in self.cells for n in (1, 2, 3)])
            self.assertTrue(all(r['observed']['failure'] == 'malformed_response' for r in rows[:4]))
            self.assertTrue(all(not r['score']['passed'] for r in rows[:4]))
            self.assertTrue(all(r['score']['passed'] for r in rows[4:]))
            self.assertEqual((output / 'result.md').read_text(), b.render_result(document))
            self.assertIn('finite_conformance_failed', (output / 'result.md').read_text())

    def test_direct_null_metrics_does_not_abort_evaluation_or_report(self):
        document = b.preparation()
        observed = copy.deepcopy(self.observations[0]); observed['metrics'] = None
        with patch.object(b, 'run_child', return_value=observed), \
             patch.object(b, 'run_checks', return_value=[{'exit_code': 0, 'command': ['test-only gate stub']}]):
            b.evaluate(document)
        run = document['runs'][-1]
        self.assertEqual(len(run['workload_repetitions']), 15)
        self.assertEqual(run['workload_runs_passed'], 0)
        self.assertIn('0/15', b.render_result(document))


class RepairPreservation(unittest.TestCase):
    def setUp(self):
        self.previous = b.preparation()
        self.archive = {'benchmark_text': json.dumps(self.previous), 'result_text': 'previous result\n',
                        'source_snapshots': {}}
        for field in ('benchmark', 'result'):
            self.archive[field + '_sha256'] = hashlib.sha256(self.archive[field + '_text'].encode()).hexdigest()

    def test_repair_preserves_original_evidence_and_reference_hash(self):
        before = copy.deepcopy(self.previous)
        repaired = b.repair_preparation(self.previous, self.archive)
        self.assertEqual(self.previous, before)
        self.assertEqual(repaired['prior_evidence']['archive'], self.archive)
        self.assertEqual(repaired['preparation']['reference_sha256'], before['preparation']['reference_sha256'])
        self.assertEqual(repaired['preparation']['revision'], 2)
        self.assertEqual(repaired['runs'], [])
        b.verify_preparation(repaired)

    def test_corrupt_archive_cannot_replace_current_evidence(self):
        self.archive['result_text'] = 'altered'
        with self.assertRaisesRegex(ValueError, 'archive text hash mismatch'):
            b.repair_preparation(self.previous, self.archive)

    def test_repair_cannot_change_reference_answers(self):
        changed = b.preparation()
        changed['preparation']['reference_sha256'] = '0' * 64
        with patch.object(b, 'preparation', return_value=changed):
            with self.assertRaisesRegex(ValueError, 'must not change reference'):
                b.repair_preparation(self.previous, self.archive)

    def test_saved_archive_tamper_rejected(self):
        repaired = b.repair_preparation(self.previous, self.archive)
        repaired['prior_evidence']['archive']['result_text'] = 'changed'
        with self.assertRaisesRegex(ValueError, 'prior evidence hash mismatch'):
            b.verify_preparation(repaired)


if __name__=='__main__': unittest.main()
